def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    threat_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > 0 and opp.get('hp', 0) > 0:
                    threat_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    high_prev = max(threat_bids) if threat_bids else (max(prev_bids) if prev_bids else 0.0)
    avg_prev = (sum(threat_bids) / len(threat_bids)) if threat_bids else ((sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0)

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.9
    elif hp <= 4:
        urgency += 0.45
    if no_water_days >= 2:
        urgency += 0.8
    elif no_water_days == 1:
        urgency += 0.35
    urgency += scarcity * 0.55
    if day >= 8:
        urgency += 0.1

    if hp <= 2 or no_water_days >= 2:
        target = max(DAILY_SALARY * 0.95, high_prev + 2.0)
    elif scarcity >= 0.7:
        target = max(DAILY_SALARY * 0.72, avg_prev + 1.5, high_prev * 0.82)
    elif scarcity >= 0.4:
        target = max(DAILY_SALARY * 0.58, avg_prev + 0.8)
    else:
        target = max(DAILY_SALARY * 0.38, avg_prev * 0.72)

    rich_threats = 0
    for opp in alive:
        if opp.get('budget', 0) >= budget and opp.get('hp', 0) > 0:
            rich_threats += 1
    if rich_threats >= 2:
        target += 4.0
    elif rich_threats == 0:
        target -= 3.0

    if high_prev >= 120 and urgency < 0.8:
        target = min(target, DAILY_SALARY * 0.52)

    if hp >= 8 and no_water_days == 0 and scarcity < 0.35:
        target = min(target, DAILY_SALARY * 0.45)

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if days_left > 0:
        reserve_floor = min(budget * 0.45, days_left * DAILY_SALARY * 0.22)
    max_spend = max(0.0, budget - reserve_floor)

    if urgency >= 1.2:
        max_spend = budget
    elif urgency >= 0.8:
        max_spend = max(max_spend, budget * 0.7)

    bid = min(target, max_spend, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday's bids from each opponent's previous_trace.
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = (sum(yesterday_bids) / len(yesterday_bids)) if yesterday_bids else 0.0

    # Base bid: aim around half salary to beat typical mid bids, but conserve.
    # Increase when supply is tighter or opponents bid aggressively yesterday.
    # Tight supply implies fewer winners and higher chance we lose without a stronger bid.
    supply_factor = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.0
    supply_factor = max(0.0, min(1.0, supply_factor))

    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 1.6:
        pressure = 0.35
    elif highest_prev_bid >= DAILY_SALARY * 1.0:
        pressure = 0.22
    elif avg_prev_bid > 0:
        pressure = 0.12

    # Urgency: if we've already missed water days, we must bid more.
    urgency = 0.0
    if no_water_days >= 3:
        urgency = 0.45
    elif no_water_days == 2:
        urgency = 0.28
    elif no_water_days == 1:
        urgency = 0.15

    # HP-based urgency (lower hp => bid more)
    hp_urgency = 0.0
    if hp <= 2:
        hp_urgency = 0.55
    elif hp <= 3:
        hp_urgency = 0.35
    elif hp <= 5:
        hp_urgency = 0.18

    # Compute target bid.
    base = DAILY_SALARY * 0.5
    target = base * (1.0 + pressure + 0.45 * supply_factor + urgency + hp_urgency)

    # Clamp to budget and keep within a reasonable range.
    # Also, if opponents were extremely high yesterday, we slightly overbid to secure a share.
    if highest_prev_bid >= DAILY_SALARY * 1.8:
        target = max(target, min(budget, highest_prev_bid * 0.95))
    elif highest_prev_bid >= DAILY_SALARY * 1.1:
        target = max(target, min(budget, highest_prev_bid * 0.7))

    # Final conservative cap to avoid going broke too early.
    cap = max(DAILY_SALARY * 0.95, budget * 0.35)  # ensure we can still survive if needed
    bid = min(budget, min(target, cap))

    # If hp is critical, ensure aggressive bid.
    if hp <= 1.5:
        bid = min(budget, DAILY_SALARY * 0.95)

    # If budget is very low, spend what we can.
    if bid < 0:
        bid = 0.0
    return bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return max(1.0, min(my_status['budget'], DAILY_SALARY * 0.1))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.6 # Default competitive bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.7:
            base_bid = highest_prev_bid + 5.0 # Try to outbid aggressive opponents
        else:
            base_bid = max(base_bid, highest_prev_bid + 1.0) # Be competitive

    bid_amount = base_bid

    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        bid_amount = DAILY_SALARY * 0.95 # Critical, bid very aggressively
    elif my_status['hp'] <= 5:
        bid_amount = max(base_bid * 1.1, DAILY_SALARY * 0.75) # Low HP, aggressive
    else:
        if day_context['supply'] >= WATER_REQ * num_alive_opponents:
            bid_amount = max(base_bid * 0.9, DAILY_SALARY * 0.5) # Ample supply, conserve
        else:
            bid_amount = max(base_bid * 1.05, DAILY_SALARY * 0.65) # Competition, competitive

    if day_context['day'] == EPISODE_DAYS:
        if my_status['hp'] > 0:
            if my_status['hp'] < 10 or my_status['no_water_days'] > 0:
                bid_amount = my_status['budget'] * 0.99 # Go almost all in on last day if needed
            else:
                bid_amount = DAILY_SALARY * 0.5 # Moderate bid if healthy on last day
        else:
            bid_amount = 0.0 # Already dead, bid 0

    final_bid = max(1.0, min(my_status['budget'], bid_amount))

    return final_bid

